import{_ as t,o as s,c as o,a0 as a}from"./chunks/framework.DQOulFGV.js";const m=JSON.parse('{"title":"9. Validation Report — Pre-Implementation Spike","description":"","frontmatter":{},"headers":[],"relativePath":"09-validation-report.md","filePath":"09-validation-report.md"}'),r={name:"09-validation-report.md"};function i(d,e,n,c,p,l){return s(),o("div",null,[...e[0]||(e[0]=[a('<h1 id="_9-validation-report-—-pre-implementation-spike" tabindex="-1">9. Validation Report — Pre-Implementation Spike <a class="header-anchor" href="#_9-validation-report-—-pre-implementation-spike" aria-label="Permalink to &quot;9. Validation Report — Pre-Implementation Spike&quot;">​</a></h1><blockquote><p>Status: <strong>COMPLETE</strong> (all experiments green). Date: 2026-08-15. This report records the de-risking experiments run <strong>before</strong> writing production code. Everything in <code>experiments/</code> is a throwaway spike; the findings below are normative inputs to the spec (deltas applied to docs 02/03/04/06/07 where marked).</p></blockquote><h2 id="_9-1-executive-summary" tabindex="-1">9.1 Executive summary <a class="header-anchor" href="#_9-1-executive-summary" aria-label="Permalink to &quot;9.1 Executive summary&quot;">​</a></h2><p>All eight experiments passed. The core bets of the specification are <strong>buildable</strong>:</p><table tabindex="0"><thead><tr><th>#</th><th>Hypothesis (from spec)</th><th>Verdict</th></tr></thead><tbody><tr><td>E1</td><td>TS compiler API extracts symbols/signatures/return types (syntactic + type-aware)</td><td>✅</td></tr><tr><td>E2</td><td><code>vi.mock</code>/<code>vi.fn</code>/<code>vi.spyOn</code>/<code>vi.mocked</code> patterns are statically detectable with the planned AST shapes</td><td>✅</td></tr><tr><td>E3</td><td>Intra-procedural provenance detects TAUT-002/TAUT-006 while keeping healthy tests quiet</td><td>✅</td></tr><tr><td>E4</td><td>TypeChecker verifies DRIFT-001 (member existence), DRIFT-003 (return assignability), DRIFT-005 (factory keys vs exports)</td><td>✅</td></tr><tr><td>E5</td><td>Import resolution: relative + tsconfig <code>paths</code> aliases + unresolvable → null</td><td>✅</td></tr><tr><td>E6</td><td><code>php-parser</code> parses PHPUnit/Mockery patterns, typed classes, namespaces, docblocks</td><td>✅</td></tr><tr><td>E7</td><td>Official MCP SDK serves the 5-tool surface with annotations + <code>structuredContent</code> over stdio</td><td>✅</td></tr><tr><td>E8</td><td><code>@momus-ignore</code> suppression syntax extracts correctly (TS regex contract + PHP docblocks)</td><td>✅</td></tr></tbody></table><p><strong>Six design-affecting discoveries</strong> were made (F1–F6 below). None invalidate the architecture; two require spec changes (TS version pin + custom host pattern; SDK subpath imports), and four are implementation notes that save the Phase-1 team from re-discovering them.</p><h2 id="_9-2-how-to-re-run" tabindex="-1">9.2 How to re-run <a class="header-anchor" href="#_9-2-how-to-re-run" aria-label="Permalink to &quot;9.2 How to re-run&quot;">​</a></h2><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">cd</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> experiments</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> install</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # typescript@^5.9, php-parser, @modelcontextprotocol/sdk, zod, tsx</span></span>\n<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> all</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">            # E1..E8, each exits non-zero on failure</span></span></code></pre></div><p>Fixture workspace: <code>experiments/fixtures/ts</code> (production <code>ledger.ts</code>/<code>db.ts</code>, test <code>ledger.test.ts</code> with planted TAUT-002/TAUT-006/DRIFT-001 + healthy controls) and <code>experiments/fixtures/php</code> (typed <code>InvoiceRepository</code>, PHPUnit test with planted TAUT-003/ DRIFT-001). The shared mini-engine lives in <code>experiments/spikes/lib/engine.ts</code>.</p><h2 id="_9-3-findings-normative" tabindex="-1">9.3 Findings (normative) <a class="header-anchor" href="#_9-3-findings-normative" aria-label="Permalink to &quot;9.3 Findings (normative)&quot;">​</a></h2><h3 id="f1-—-pin-typescript-5-9-ts-7-is-not-usable-programmatically-yet" tabindex="-1">F1 — Pin <code>typescript@^5.9</code>; TS 7 is not usable programmatically (yet) <a class="header-anchor" href="#f1-—-pin-typescript-5-9-ts-7-is-not-usable-programmatically-yet" aria-label="Permalink to &quot;F1 — Pin `typescript@^5.9`; TS 7 is not usable programmatically (yet)&quot;">​</a></h3><p><code>typescript@7.0.2</code> (the native compiler) exposes <strong>no programmatic API</strong> from ESM: the npm package&#39;s ESM entry exports only <code>{ default, module.exports, version }</code>, <code>module.exports</code> is opaque, and <code>lib/typescript.js</code> is blocked by the exports map. The stable, documented API is the 5.x line. <strong>Spec delta:</strong> §6.1 dependency table + §2.2.2 → pin <code>typescript@^5.9</code> (<code>^5</code> range), add a tracked migration risk for TS7 (their JS API is still maturing).</p><h3 id="f2-—-mcp-sdk-use-subpath-imports-the-root-entry-is-broken-in-the-published-tarball" tabindex="-1">F2 — MCP SDK: use subpath imports; the root entry is broken in the published tarball <a class="header-anchor" href="#f2-—-mcp-sdk-use-subpath-imports-the-root-entry-is-broken-in-the-published-tarball" aria-label="Permalink to &quot;F2 — MCP SDK: use subpath imports; the root entry is broken in the published tarball&quot;">​</a></h3><p><code>import &#39;@modelcontextprotocol/sdk&#39;</code> fails on every published version checked (1.12.0, 1.25.3, 1.29.0, 1.30.0): the tarball ships <code>dist/esm/{client,server,shared,validation,…}</code> but <strong>never the root <code>index.js</code>/<code>index.d.ts</code></strong> the exports map points at. Working imports:</p><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { McpServer } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@modelcontextprotocol/sdk/server/mcp.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { StdioServerTransport } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@modelcontextprotocol/sdk/server/stdio.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { Client } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@modelcontextprotocol/sdk/client/index.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span>\n<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">import</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { StdioClientTransport } </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">from</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> &#39;@modelcontextprotocol/sdk/client/stdio.js&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p><strong>Spec delta:</strong> §6.1 → document subpath imports, pin <code>@modelcontextprotocol/sdk@^1.29</code> (works on 1.30.0), note the root-entry packaging bug. <code>zod</code> is required for tool schemas (peer dep of the SDK) — add to the dependency table.</p><h3 id="f3-—-keeps-a-parenthesizedexpression-in-the-ts-ast" tabindex="-1">F3 — <code>() =&gt; ({...})</code> keeps a ParenthesizedExpression in the TS AST <a class="header-anchor" href="#f3-—-keeps-a-parenthesizedexpression-in-the-ts-ast" aria-label="Permalink to &quot;F3 — `() =&gt; ({...})` keeps a ParenthesizedExpression in the TS AST&quot;">​</a></h3><p><code>vi.mock(&#39;x&#39;, () =&gt; ({ Db: vi.fn() }))</code> parses the factory body as <code>ParenthesizedExpression(ObjectLiteral)</code>. Factory-key extraction must unwrap. Implementation note for <code>parser-typescript</code> (E2 hit this).</p><h3 id="f4-—-expect-a-tobe-b-the-operands-sit-inside-a-propertyaccess-chain" tabindex="-1">F4 — <code>expect(A).toBe(B)</code>: the operands sit inside a PropertyAccess chain <a class="header-anchor" href="#f4-—-expect-a-tobe-b-the-operands-sit-inside-a-propertyaccess-chain" aria-label="Permalink to &quot;F4 — `expect(A).toBe(B)`: the operands sit inside a PropertyAccess chain&quot;">​</a></h3><p>The inner <code>expect(A)</code> call&#39;s parent is the <code>PropertyAccessExpression</code> (<code>expect(A).toBe</code>), not the matcher call. Assertion walks must traverse PropertyAccess nodes up to the matcher call (handles <code>.resolves.toBe</code> chains too). Implementation note for the rule engine (E3 hit this; also: only descend to the <em>nearest</em> enclosing CallExpression — bounded, so <code>foo(expect(x))</code> is not misread as a matcher call).</p><h3 id="f5-—-critical-ts-createprogram-files-have-no-parent-pointers-—-use-a-custom-host" tabindex="-1">F5 — CRITICAL: <code>ts.createProgram</code> files have NO parent pointers — use a custom host <a class="header-anchor" href="#f5-—-critical-ts-createprogram-files-have-no-parent-pointers-—-use-a-custom-host" aria-label="Permalink to &quot;F5 — CRITICAL: `ts.createProgram` files have NO parent pointers — use a custom host&quot;">​</a></h3><p>Source files produced by the program&#39;s default host are parsed with <code>setParentNodes: false</code>, so <code>node.parent</code> is <code>undefined</code> everywhere. Any scope/block/assertion analysis that walks up from a node silently finds nothing (this manifested as &quot;1st call empty, 2nd call full&quot; — a trap for the unwary, since nothing throws).</p><p><strong>Fix (the typescript-eslint pattern), validated in E7:</strong> pre-parse every file with <code>ts.createSourceFile(path, text, target, /*setParentNodes*/ true)</code> and hand those instances to the program via a custom <code>CompilerHost.getSourceFile</code>. The checker then resolves types on the same instances.</p><p><strong>Spec delta:</strong> §2.2.2 + §7 Phase 1 → the TS parser MUST build the program over a custom host with parent-enabled source files; never mix a fresh <code>createSourceFile</code> instance with checker calls (F6).</p><h3 id="f6-—-checker-type-queries-require-the-program-s-own-sourcefile-instance" tabindex="-1">F6 — Checker type queries require the program&#39;s own SourceFile instance <a class="header-anchor" href="#f6-—-checker-type-queries-require-the-program-s-own-sourcefile-instance" aria-label="Permalink to &quot;F6 — Checker type queries require the program&#39;s own SourceFile instance&quot;">​</a></h3><p><code>checker.getTypeAtLocation(node)</code> on a node from a <em>freshly created</em> <code>createSourceFile</code> (same text, same path) silently degrades to <code>any</code> — so <code>vi.spyOn(service, &#39;totalForX&#39;)</code> reported &quot;does not exist on <strong>any</strong>&quot; instead of <code>LedgerService</code>. Corollary of F5: parse once, use that instance for both syntax analysis and checker queries. <strong>Spec delta:</strong> §2.4.2 resolution rule — single-source-file-instance invariant.</p><h3 id="f7-—-async-methods-drift-003-must-compare-against-the-promise-s-resolved-type" tabindex="-1">F7 — Async methods: DRIFT-003 must compare against the promise&#39;s resolved type <a class="header-anchor" href="#f7-—-async-methods-drift-003-must-compare-against-the-promise-s-resolved-type" aria-label="Permalink to &quot;F7 — Async methods: DRIFT-003 must compare against the promise&#39;s resolved type&quot;">​</a></h3><p><code>LedgerService.totalFor(): Promise&lt;Invoice&gt;</code> — comparing a stub shape against <code>Promise&lt;Invoice&gt;</code> always fails. The checker provides <code>checker.getPromisedTypeOfPromise(type)</code>; DRIFT-003 unwraps it for async methods (this also confirms the spec&#39;s §3.4 rule — now with a concrete API). <strong>Spec delta:</strong> §3.4 assignability table → add the unwrap API reference.</p><h3 id="f8-—-mcp-stdio-servers-must-never-write-to-stdout" tabindex="-1">F8 — MCP stdio servers must never write to stdout <a class="header-anchor" href="#f8-—-mcp-stdio-servers-must-never-write-to-stdout" aria-label="Permalink to &quot;F8 — MCP stdio servers must never write to stdout&quot;">​</a></h3><p>The server&#39;s debug <code>console.log</code>s corrupted the stdio transport: the first <code>tools/call</code> response came back truncated/misparsed, the second succeeded. All diagnostics must go to <code>stderr</code> or an injectable logger (default no-op in server mode). <strong>Spec delta:</strong> §4.1 — add a &quot;transport hygiene&quot; rule: no stdout writes; logging goes to stderr/logger.</p><h3 id="f9-—-php-parser-actual-node-shapes-differ-from-naive-expectations" tabindex="-1">F9 — php-parser actual node shapes (differ from naive expectations) <a class="header-anchor" href="#f9-—-php-parser-actual-node-shapes-differ-from-naive-expectations" aria-label="Permalink to &quot;F9 — php-parser actual node shapes (differ from naive expectations)&quot;">​</a></h3><p>Validated against <code>php-parser@3.7.0</code>:</p><ul><li>No <code>methodcall</code> kind: <code>$obj-&gt;method()</code> parses as <code>call { what: propertylookup { what: &lt;obj&gt;, offset: &lt;identifier&gt; } }</code>; the method name is <code>call.what.offset.name</code>.</li><li>Class/<code>Foo::class</code> targets: <code>staticlookup { what: name, offset: identifier(class) }</code>.</li><li>Names are <strong>identifier nodes</strong> (<code>{kind:&#39;identifier&#39;, name:&#39;X&#39;}</code>), not strings — on classes, methods, parameters.</li><li>Parameter types: <code>param.type</code> with kind <code>typereference</code>; return types: <code>method.type</code> with kind <strong><code>name</code></strong> (not <code>typereference</code>).</li><li>Method bodies are <code>block</code> nodes with <code>children</code> (not arrays).</li><li>Assignments are <code>assign</code> statements inside <code>expressionstatement</code>.</li><li>Docblocks attach via <code>node.leadingComments</code> when <code>parser.extractDoc: true</code> — validated for <code>/** @momus-ignore */</code>.</li><li>Chain traversal <code>$repo-&gt;expects(...)-&gt;method(&#39;fetchAll&#39;)</code> → <code>[&#39;expects&#39;, &#39;method&#39;]</code> via recursive <code>call.what</code> descent.</li></ul><p><strong>Spec delta:</strong> §2.5.2 mock catalog → replace &quot;AST trigger&quot; descriptions with these concrete shapes so Phase 2 implements them directly.</p><h3 id="f10-—-mcp-sdk-supports-everything-§4-needs" tabindex="-1">F10 — MCP SDK supports everything §4 needs <a class="header-anchor" href="#f10-—-mcp-sdk-supports-everything-§4-needs" aria-label="Permalink to &quot;F10 — MCP SDK supports everything §4 needs&quot;">​</a></h3><p><code>McpServer.tool()</code> accepts annotations (<code>readOnlyHint</code>, <code>destructiveHint</code>, <code>idempotentHint</code>, <code>openWorldHint</code>, <code>title</code>) and returns them in <code>tools/list</code>; <code>structuredContent</code> round-trips (including arrays); <code>isError: true</code> works for tool execution errors; tool order is stable; <code>inputSchema</code> is generated from zod. Note: <code>McpServer.tool()</code> has <strong>no <code>outputSchema</code> parameter</strong> in SDK 1.29/1.30 — <code>outputSchema</code> in the spec is aspirational (harmless: clients validate <code>structuredContent</code>; keep it out of the tool registration for now). <strong>Spec delta:</strong> §4.2 note — <code>outputSchema</code> documented but not wired in v1 (SDK gap).</p><h3 id="f11-—-suppression-regex-contract-holds-ts" tabindex="-1">F11 — Suppression regex contract holds (TS) <a class="header-anchor" href="#f11-—-suppression-regex-contract-holds-ts" aria-label="Permalink to &quot;F11 — Suppression regex contract holds (TS)&quot;">​</a></h3><p>All forms from §3.5.1 verified: line-above, trailing, scoped single/multi-rule, docblock, file-banner, and both negative cases (misspelled directive, space after colon) stay quiet.</p><h2 id="_9-4-spec-deltas-applied" tabindex="-1">9.4 Spec deltas applied <a class="header-anchor" href="#_9-4-spec-deltas-applied" aria-label="Permalink to &quot;9.4 Spec deltas applied&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Doc</th><th>Change</th></tr></thead><tbody><tr><td><code>02-architecture.md</code> §2.2.2</td><td>Pin <code>typescript@^5.9</code>; custom-host pattern with <code>setParentNodes: true</code>; single-source-file-instance invariant (F5/F6)</td></tr><tr><td><code>02-architecture.md</code> §2.2.3 / §2.5.2</td><td>Concrete php-parser node shapes (F9)</td></tr><tr><td><code>03-analysis-algorithms.md</code> §3.4</td><td><code>getPromisedTypeOfPromise</code> unwrap for async returns (F7)</td></tr><tr><td><code>04-mcp-tool-definitions.md</code> §4.1</td><td>Transport hygiene rule: no stdout writes (F8); <code>outputSchema</code> note (F10)</td></tr><tr><td><code>06-repository-layout.md</code> §6.1</td><td>SDK subpath imports + version pin + zod (F2); typescript pin + TS7 risk (F1)</td></tr><tr><td><code>07-roadmap.md</code> Phase 1</td><td>Deliverable: parent-enabled custom host; add SDK subpath imports to scaffold</td></tr></tbody></table><h2 id="_9-5-remaining-risks-not-yet-spiked" tabindex="-1">9.5 Remaining risks (not yet spiked) <a class="header-anchor" href="#_9-5-remaining-risks-not-yet-spiked" aria-label="Permalink to &quot;9.5 Remaining risks (not yet spiked)&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Risk</th><th>Why it remains</th><th>Suggested spike (Phase 1)</th></tr></thead><tbody><tr><td>Large-repo perf (10k+ LOC budgets §2.7)</td><td>Spike used a 200-LOC fixture</td><td>bench fixture repo; measure program build + incremental</td></tr><tr><td><code>beforeEach</code>-configured mocks across <code>describe</code> scopes</td><td>Spike was intra-test-function</td><td>✅ resolved in Step 2: module and nested <code>describe</code> scopes are fixture-tested</td></tr><tr><td>PHP type resolution across files (FQCN matching for DRIFT-003)</td><td>E6 validated syntax only</td><td>✅ initial slice: Composer PSR-4 + classmap resolution are fixture-tested; DRIFT-003 assignability for PHP remains</td></tr><tr><td>Jest automock (<code>jest.mock(&#39;x&#39;)</code> no factory) member checks</td><td>Out of scope by design (DRIFT-000)</td><td>none needed</td></tr><tr><td>Mockery closure-form (<code>Mockery::mock(&#39;F&#39;, fn($m) =&gt; …)</code>)</td><td>Not in spike fixture</td><td>add fixture in Phase 2</td></tr></tbody></table><h2 id="_9-6-repo-state" tabindex="-1">9.6 Repo state <a class="header-anchor" href="#_9-6-repo-state" aria-label="Permalink to &quot;9.6 Repo state&quot;">​</a></h2><ul><li><code>experiments/</code> — package.json (<code>npm run e1..e8</code>, <code>npm run all</code>), <code>fixtures/</code>, <code>spikes/</code>, <code>spikes/lib/engine.ts</code>. Throwaway; excluded from the Phase-0 repo skeleton.</li><li>Root <code>.gitignore</code> added (node_modules, tsbuildinfo, .momus cache).</li><li>All docs updated per §9.4.</li></ul>',44)])])}const u=t(r,[["render",i]]);export{m as __pageData,u as default};
